SELECT 'Product.version' AS source, version AS value, count(*) FROM "Product" GROUP BY 1,2 UNION ALL SELECT 'FactoryBoothVersionCode.code', code, 1 FROM "FactoryBoothVersionCode" UNION ALL SELECT 'MrpRecipeVersion.label', label, count(*) FROM "MrpRecipeVersion" GROUP BY 1,2 UNION ALL SELECT 'InventoryUnit.productVersion', "productVersion", count(*) FROM "InventoryUnit" GROUP BY 1,2 ORDER BY 1,3 DESC
